TLM.f("Sancti/06-22",{"officium":"S. Paulini Episcopi et Confessoris","rule":["vide C4;","Gloria"],"fallback":"Commune/C4","from":{"GradualeP":"Commune/C4","Tractus":"Commune/C4"},"sections":{"Introitus":[{"k":"ref","la":"Ps 131,9-10"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes tui, Dómine, índuant justítiam, et sancti tui exsúltent: propter David servum tuum, non avértas fáciem Christi tui. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui ómnia pro te in hoc sǽculo relinquéntibus, céntuplum in futúro et vitam ætérnam promisísti: concéde propítius; ut, sancti Pontíficis Paulíni vestígiis inhæréntes, valeámus terréna despícere et sola cœléstia desideráre:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 8:9-15"},{"k":"text","la":"Fratres: Scitis grátiam Dómini nostri Jesu Christi, quóniam propter vos egénus factus est, cum esset dives, ut illíus inópia vos dívites essétis. Et consílium in hoc do: hoc enim vobis útile est, qui non solum fácere, sed et velle cœpístis ab anno prióre: nunc vero et facto perfícite: ut, quemádmodum promptus est ánimus voluntátis, ita sit et perficiéndi ex eo quod habétis. Si enim volúntas prompta est, secúndum id quod habet, accépta est, non secúndum id quod non habet. Non enim ut áliis sit remíssio, vobis autem tribulátio, sed ex æqualitáte. In præsénti témpore vestra abundántia illórum inópiam súppleat: ut et illórum abundántia vestræ inópiæ sit suppleméntum, ut fiat æquálitas, sicut scriptum est: Qui multum, non abundávit: et qui módicum, non minorávit."}],"Graduale":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:32-34"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit."}],"Offertorium":[{"k":"ref","la":"Ps 88:21-22"},{"k":"text","la":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Da nobis, Dómine, perféctæ caritátis sacrifícium, exémplo sancti Pontíficis Paulíni, cum altáris oblatióne conjúngere: et beneficéntiæ stúdio sempitérnam misericórdiam promeréri."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Tríbue nobis per hæc sancta, Dómine, illum pietátis et humilitátis afféctum, quem ex hoc divíno fonte hausit sanctus Póntifex tuus Paulínus: et, ipsíus intercessióne, in omnes, qui te deprecántur, grátiæ tuæ divítias benígnus effúnde."},{"k":"macro","name":"Per Dominum"}]},"hr":{"a9bf8f9449951217":{"t":"Ps 131, 9-10, Ps 131, 1\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve revnosti njegove.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga."},"28177470d301a4d9":{"t":"<i>Pomolimo se</i>.\nBože, koji si onima što radi tebe sve ostave na ovom svijetu obećao stostruko u budućnosti i vječni život, daj milostiv, da idući stopama svetog biskupa Paulina uzmognemo prezreti zemaljsko i željeti jedino nebesko:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"cd757dddf2c65e5a":{"t":"2 Kor 8, 9-15\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, znate milosti Gospodina našega Isusa Krista koji je radi nas postao siromah premda je bio bogat. I savjet dajem u tom, jer to koristi vama koji ste i voljom i djelom započeli od prošle godine. A sad ostvarite to da kao što je volja bila spremna htjeti da prema mogućnosti bude spremna i izvršiti. Jer ako tko ima spremnu volju, mio je po onom što ima, a ne po onom što nema. Ali ne tako da drugima bude olakšica a vama potreba, nego neka bude jednakost. U sadašnje vrijeme neka vaš suvišak pomogne njihovoj oskudici te bude jednakost kao što je pisano: Tko je mnogo sakupio nije imao više, a tko je malo nije imao manje."},"16468be514c64800":{"t":"Sir 44, 16, Sir 44, 20\n(Sir 44, 16) Evo velikog svećenika koje se za svoga života svidio Bogu. (Sir 44, 20) Nitko mu nije bio ravan u izvršavanju zakona Svevišnjega.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>."},"1cac10fd63222759":{"t":"Lk 12, 32-34\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Nemojte se bojati, malo stado, jer je vaš Otac odlučio dati vam kraljevstvo. Prodajte što imate i dajte milostinju. Načinite sebi torbe koje neće ostarjeti, neprolazno blago na nebu, kamo se ne približava lupež, niti izjeda moljac. Jer gdje je vaše blago, ondje će biti i vaše srce."},"c1545941e0b9c017":{"t":"Ps 88, 21-22\nNašao sam Davida, slugu svojega, pomazao sam ga svojim svetim uljem. S njim će biti ruka moja i krijepit će ga desnica moja."},"79879fba1a045043":{"t":"Daj nam, Gospodine, sjediniti po primjeru svetog biskupa Paulina žrtvu savršene ljubavi s prinosom na oltaru i revnošću u dobročinstvima zaslužiti vječno milosrđe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."},"b850f55958e0f668":{"t":"<i>Pomolimo se</i>.\nUdijeli nam, Gospodine, po ovom svetotajstvu onaj osjećaj dobrote i poniznosti, kojega je iz ovog božanskog izvora crpio sveti tvoj biskup Paulin, i dobrostiv izlij, po njegovu zagovoru, bogatstvo svoje milosti na sve koji te zazivaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
